import {Router} from 'express';
import {fail,route,integer} from './errors.js';
const fields=['id','name','description','priceCents','category','stock','imageUrl'];
function validate(product,categories) {
 if(typeof product.id!=='string'||!/^[A-Za-z0-9._~-]+$/.test(product.id))fail(400,'INVALID_INPUT','id must be URL-safe');
 if(typeof product.name!=='string'||product.name.trim().length<1||product.name.length>100)fail(400,'INVALID_INPUT','name must contain 1–100 characters');
 if(typeof product.description!=='string'||product.description.length>2000)fail(400,'INVALID_INPUT','description must contain at most 2000 characters');
 integer(product.priceCents,1,Number.MAX_SAFE_INTEGER,'priceCents');integer(product.stock,0,Number.MAX_SAFE_INTEGER,'stock');
 if(typeof product.category!=='string'||!categories.has(product.category))fail(400,'INVALID_INPUT','category must be a catalog category');
 try {if(typeof product.imageUrl!=='string')throw new Error();new URL(product.imageUrl);} catch {fail(400,'INVALID_INPUT','imageUrl must be a URL');}
}
export function adminRoutes(store,token) {
 const router=Router();
 router.use('/admin',(req,res,next)=>{if(!token||req.get('x-admin-token')!==token)return res.status(401).json({error:{code:'UNAUTHORIZED',message:'Valid admin token required'}});next();});
 router.post('/admin/products',route(async(req,res)=>{
  const created=await store.exclusive(async()=>{
   if(!req.body||Array.isArray(req.body)||Object.keys(req.body).some(key=>!fields.includes(key)))fail(400,'INVALID_INPUT','Invalid product fields');
   const products=await store.read('products');validate(req.body,new Set(products.map(p=>p.category)));
   if(products.some(p=>p.id===req.body.id))fail(400,'INVALID_INPUT','Product id is already taken');
   const product=Object.fromEntries(fields.map(key=>[key,req.body[key]]));await store.write('products',[...products,product]);return product;
  });res.status(201).json(created);
 }));
 router.patch('/admin/products/:id',route(async(req,res)=>{
  const updated=await store.exclusive(async()=>{
   if(!req.body||Array.isArray(req.body)||!Object.keys(req.body).length||Object.keys(req.body).some(key=>key==='id'||!fields.includes(key)))fail(400,'INVALID_INPUT','Updates may change product fields except id');
   const products=await store.read('products');const index=products.findIndex(p=>p.id===req.params.id);if(index<0)fail(404,'NOT_FOUND','Product not found');
   const product={...products[index],...req.body};validate(product,new Set(products.map(p=>p.category)));products[index]=product;await store.write('products',products);return product;
  });res.json(updated);
 }));
 router.get('/admin/orders',route(async(req,res)=>res.json((await store.read('orders')).slice().reverse().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)))));
 return router;
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {fixture} from './helpers.js';
const token={'x-admin-token':'test-secret'};
const product={id:'test-item',name:'Test Item',description:'A useful object',priceCents:101,category:'Home',stock:5,imageUrl:'https://example.com/item.png'};
test('admin is denied with missing, wrong or disabled token',async t=>{
 const {request}=await fixture(t,{adminToken:'test-secret'});
 for(const path of ['/api/admin/orders','/api/admin/products'])assert.equal((await request(path,path.endsWith('products')?'POST':'GET',path.endsWith('products')?product:undefined)).status,401);
 assert.equal((await request('/api/admin/orders','GET',undefined,{'x-admin-token':'wrong'})).body.error.code,'UNAUTHORIZED');
 const disabled=await fixture(t,{adminToken:null});assert.equal((await disabled.request('/api/admin/orders','GET',undefined,token)).status,401);
});
test('admin create, duplicate, validation, update and order listing',async t=>{
 const {request}=await fixture(t,{adminToken:'test-secret'});
 assert.equal((await request('/api/admin/products','POST',product,token)).status,201);
 assert.equal((await request('/api/admin/products','POST',product,token)).status,400);
 for(const change of [{name:''},{priceCents:1.5},{priceCents:0},{stock:-1},{category:'Unknown'},{imageUrl:'not-url'},{description:'x'.repeat(2001)},{id:'not safe'}])assert.equal((await request('/api/admin/products','POST',{...product,id:'other',...change},token)).status,400);
 assert.equal((await request('/api/admin/products','POST',{id:'missing-fields'},token)).status,400);
 assert.equal((await request('/api/admin/products/test-item','PATCH',{id:'new'},token)).status,400);
 assert.equal((await request('/api/admin/products/missing','PATCH',{stock:2},token)).status,404);
 const updated=await request('/api/admin/products/test-item','PATCH',{priceCents:201,name:'Updated Item',stock:9},token);assert.equal(updated.status,200);assert.equal(updated.body.priceCents,201);assert.equal(updated.body.id,'test-item');
 const orders=[];
 for(let i=0;i<2;i++){const cart=(await request('/api/carts','POST')).body;await request('/api/carts/'+cart.id+'/items','POST',{productId:'test-item',quantity:1});orders.push((await request('/api/checkout','POST',{cartId:cart.id,email:'admin@example.com'})).body);}
 const listed=await request('/api/admin/orders','GET',undefined,token);assert.equal(listed.status,200);assert.equal(listed.body.length,2);assert.equal(listed.body[0].id,orders[1].id);
 await request('/api/admin/products/test-item','PATCH',{priceCents:301,name:'Changed Again'},token);
 assert.equal((await request('/api/orders/'+orders[0].id)).body.items[0].priceCents,201);
 assert.equal((await request('/api/orders/'+orders[0].id)).body.items[0].name,'Updated Item');
});
